'use server'

import { updateTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  [key: string]: any
}

const posts: Post[] = []

export async function createPost(
  arg1?: any,
  arg2?: any
): Promise<Post> {
  let data = arg1
  if (arg2 instanceof FormData) {
    data = arg2
  }

  const postData: Record<string, any> = {}

  if (data instanceof FormData) {
    for (const [key, value] of data.entries()) {
      postData[key] = value
    }
  } else if (data && typeof data === 'object') {
    Object.assign(postData, data)
  }

  const post: Post = {
    id: postData.id ? String(postData.id) : (posts.length + 1).toString(),
    title: postData.title ? String(postData.title) : '',
    content: (postData.content ?? postData.body) ? String(postData.content ?? postData.body) : '',
    ...postData,
  }

  posts.push(post)

  updateTag('posts')

  return post
}

export async function createNewPost(
  arg1?: any,
  arg2?: any
): Promise<Post> {
  return createPost(arg1, arg2)
}

export default createPost
